#include "model.hpp"
#include <iostream>
using State=Eigen::Matrix<double,13,1>;
int main(int argc,char**argv){Json output=Json::array();for(int arg=1;arg<argc;++arg){auto r=read(argv[arg]);Model model(r["vehicle"]);std::vector<State> states;std::vector<Eigen::Vector4d> controls;for(auto&s:r["states"]){State x;for(int k=0;k<13;++k)x[k]=s[k];states.push_back(x);}for(auto&u:r["controls"]){Eigen::Vector4d v;for(int k=0;k<4;++k)v[k]=u[k];controls.push_back(v);}double h=r["nominal_time_s"].get<double>()/controls.size();Json tests=Json::array();std::vector<State> previous;for(int sub:{16,32,64}){State x=states.front();std::vector<State> trajectory{x};double error=0,localerror=0,difference=0;for(size_t i=0;i<controls.size();++i){State local=states[i];for(int k=0;k<sub;++k){x=model.rk4(x,controls[i],h/sub);local=model.rk4(local,controls[i],h/sub);}trajectory.push_back(x);error=std::max(error,(x.head<3>()-states[i+1].head<3>()).norm());localerror=std::max(localerror,(local-states[i+1]).cwiseAbs().maxCoeff());if(!previous.empty())difference=std::max(difference,(x.head<3>()-previous[i+1].head<3>()).norm());}tests.push_back({{"substeps",sub},{"max_position_difference_to_nodes_m",error},{"max_local_state_defect",localerror},{"max_position_difference_to_previous_refinement_m",difference}});previous=trajectory;}
Json extra;auto opt=read(fs::path(argv[arg]).parent_path()/"optimizer.json");auto z=opt["x"].get<std::vector<double>>();int W=r["progress"][0].size(),width=17+3*W;double sum=0,maxlambda=0;int count=0;for(size_t i=0;i<controls.size();++i){double lambda=z[14+W+i*width+17+W-1];sum+=lambda;maxlambda=std::max(maxlambda,lambda);if(lambda>1e-4)++count;}extra={{"last_waypoint_sum_lambda",sum},{"last_waypoint_max_lambda",maxlambda},{"last_waypoint_nodes_lambda_above_1e4",count}};
output.push_back({{"result",argv[arg]},{"h_s",h},{"final_quaternion_norm",states.back().segment<4>(6).norm()},{"final_acceleration_norm",model.derivative(states.back(),controls.back()).segment<3>(3).norm()},{"integration",tests},{"progress",extra}});}std::cout<<output.dump(2)<<'\n';}
